function compute(inputs) {
  const z = inputs.logits;
  const T = inputs.T;
  const K = z.length;
  // Compute exp(z_i / T)
  const expZ = z.map(zi => Math.exp(zi / T));
  const sumExp = expZ.reduce((a, b) => a + b, 0);
  const p = expZ.map(e => e / sumExp);
  // Build table rows: class, z_i, exp(z_i/T), p_i
  const rows = [];
  for (let i = 0; i < K; i++) {
    rows.push([`Class ${i+1}`, z[i].toFixed(2), expZ[i].toFixed(4), p[i].toFixed(4)]);
  }
  // Insight: compare max probability to uniform 1/K
  const maxP = Math.max(...p);
  const uniform = 1 / K;
  let insight = '';
  if (Math.abs(maxP - uniform) < 0.01) {
    insight = `Distribution is nearly uniform (max p = ${maxP.toFixed(3)} ≈ 1/${K} = ${uniform.toFixed(3)}).`;
  } else if (maxP > 0.9) {
    insight = `Distribution is very sharp (max p = ${maxP.toFixed(3)}).`;
  } else {
    insight = `Max probability is ${maxP.toFixed(3)}.`;
  }
  return {
    probabilities: p,
    table: {
      columns: ['Class', 'z_i', 'exp(z_i/T)', 'p_i'],
      rows: rows
    },
    insight: insight
  };
}
